using System.Text.Json;
using Xunit;

namespace BritanniaRenaissance.Content.Tests;

/// <summary>
/// The Cove spawn areas (owner sign-off 2026-10-19, docs/Cove-Spawn-Areas-Evidence.md): the Greater Britain rules in smaller rings
/// around Cove (beginner within about 180 tiles, step-up to 280, dangerous to 400), Britain's plan winning every overlap, the orc
/// fort a tougher outlier (plain orcs at the gate, lords and mages in the keep), step-up and harder spawners spread into groups of
/// at most 3, and single flavor objects written into the map's statics. Generated by tools/spawn-design (areas-cove.json,
/// build_data.py, place_flavor.py).
/// </summary>
public class CoveSpawnAreasTests
{
    private static readonly string Root = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "data", "world-generation", "alpha2b");
    private const int CoveX = 2243, CoveY = 1178;

    private static readonly HashSet<string> Dangerous = new(StringComparer.Ordinal)
    {
        "Troll", "Ettin", "Ogre", "Gargoyle", "Gazer", "Corpser", "Reaper", "DireWolf", "GrizzlyBear", "SkeletalKnight", "BoneKnight",
        "Wisp", "OrcishMage", "OrcishLord", "EarthElemental", "AirElemental", "WaterElemental", "Lich", "Mummy"
    };

    private static List<JsonElement> Load(string name) =>
        JsonDocument.Parse(File.ReadAllText(Path.Combine(Root, name))).RootElement.EnumerateArray().Select(e => e.Clone()).ToList();

    private static List<JsonElement> Spawners() => Load("cove-spawn-areas.json");

    private static JsonElement Manifest() => JsonDocument.Parse(File.ReadAllText(Path.Combine(Root, "world-generation.json"))).RootElement;

    private static double FromCove(JsonElement s)
    {
        var (x, y) = GreaterBritainSpawnAreasTests.At(s);
        return Math.Sqrt((x - CoveX) * (x - CoveX) + (y - CoveY) * (y - CoveY));
    }

    [Fact]
    public void ManifestListsCoveJustBeforeBritainSoBritainWins()
    {
        var spawnFiles = Manifest().GetProperty("customSpawnerFiles").EnumerateArray().Select(e => e.GetString()).ToList();
        Assert.Equal("cove-spawn-areas.json", spawnFiles[^2]);
        Assert.Equal("greater-britain-spawn-areas.json", spawnFiles[^1]);
    }

    [Fact]
    public void GuidsAndPlacesAreUniqueAndNeverBritains()
    {
        var all = Spawners();
        Assert.True(all.Count >= 100);
        Assert.Equal(all.Count, all.Select(s => s.GetProperty("guid").GetString()).Distinct(StringComparer.OrdinalIgnoreCase).Count());
        Assert.Equal(all.Count, all.Select(GreaterBritainSpawnAreasTests.At).Distinct().Count());
        Assert.All(all, s => Assert.Equal("Felucca", s.GetProperty("map").GetString()));

        var britain = Load("greater-britain-spawn-areas.json");
        var britainGuids = britain.Select(s => s.GetProperty("guid").GetString()!).ToHashSet(StringComparer.OrdinalIgnoreCase);
        var britainPlaces = britain.Select(GreaterBritainSpawnAreasTests.At).ToHashSet();
        Assert.All(all, s => Assert.DoesNotContain(s.GetProperty("guid").GetString()!, britainGuids));
        Assert.All(all, s => Assert.DoesNotContain(GreaterBritainSpawnAreasTests.At(s), britainPlaces));
        // Britain's plan wins where the two meet: Cove leaves Britain's rectangle alone
        Assert.All(all, s =>
        {
            var (x, y) = GreaterBritainSpawnAreasTests.At(s);
            Assert.False(x is >= 1000 and < 2000 && y is >= 1250 and < 2050, $"{x},{y} is inside Britain's plan");
        });
    }

    [Fact]
    public void NoPostEraCreatureIsSpawned()
    {
        var excluded = Manifest().GetProperty("excludedSpawnerTypes").EnumerateArray().Select(e => e.GetString()!).ToHashSet(StringComparer.OrdinalIgnoreCase);
        Assert.All(Spawners(), s => Assert.DoesNotContain(GreaterBritainSpawnAreasTests.Names(s), excluded.Contains));
    }

    [Fact]
    public void NothingDangerousSpawnsAtCovesDoorstep()
    {
        foreach (var s in Spawners().Where(s => FromCove(s) < 180))
        {
            Assert.DoesNotContain(GreaterBritainSpawnAreasTests.Names(s), Dangerous.Contains);
        }
    }

    [Fact]
    public void TheOrcFortHasPlainOrcsAtTheGateAndLordsAndMagesInTheKeep()
    {
        var all = Spawners();
        var gate = all.Where(s => s.GetProperty("name").GetString()!.StartsWith("Orc Fort Gate", StringComparison.Ordinal)).ToList();
        var keep = all.Where(s => s.GetProperty("name").GetString()!.StartsWith("Orc Fort Keep", StringComparison.Ordinal)).ToList();
        Assert.NotEmpty(gate);
        Assert.NotEmpty(keep);
        Assert.All(gate, s => Assert.Equal(["Orc"], GreaterBritainSpawnAreasTests.Names(s)));
        Assert.All(gate, s => Assert.True(GreaterBritainSpawnAreasTests.At(s).Y < 1372));
        Assert.All(keep, s => Assert.Contains("OrcishLord", GreaterBritainSpawnAreasTests.Names(s)));
        Assert.All(keep, s => Assert.Contains("OrcishMage", GreaterBritainSpawnAreasTests.Names(s)));
        Assert.All(keep, s => Assert.True(GreaterBritainSpawnAreasTests.At(s).Y >= 1372));
    }

    [Fact]
    public void StepUpAndHarderSpawnersHoldAtMostThree() =>
        GreaterBritainSpawnAreasTests.AssertSpreadInGroupsOfThree(Spawners(), "Orc Fort Keep");

    [Fact]
    public void EveryCountCanBeFilled()
    {
        foreach (var s in Spawners())
        {
            Assert.True(s.GetProperty("entries").EnumerateArray().Sum(e => e.GetProperty("maxCount").GetInt32()) >= s.GetProperty("count").GetInt32());
        }
    }

    [Fact]
    public void FlavorObjectsAreSpreadOutInEraAndClearOfBritainsPieces()
    {
        var playerItems = new HashSet<int> { 0x0DFA, 0x0DFB, 0x0A55, 0x0A56, 0x09A9, 0x0E3C, 0x1402, 0x1853, 0x0F36, 0x0ED4, 0x0ECA, 0x0ECB, 0x0ECC, 0x1AE0, 0x1AE2, 0x0F34, 0x0F3B, 0x1363, 0x1B09, 0x1B0A };
        var blocking = new HashSet<int> { 0x0C2D, 0x0ED5, 0x10D9, 0x1368, 0x1369, 0x136A, 0x136B, 0x136C };
        List<(int X, int Y)> Pieces(string file, bool check)
        {
            var patch = JsonDocument.Parse(File.ReadAllText(Path.Combine(Root, "..", "..", "map-patches", file))).RootElement;
            Assert.Equal(0, patch.GetProperty("map").GetInt32());
            var list = new List<(int X, int Y)>();
            foreach (var piece in patch.GetProperty("statics").EnumerateArray())
            {
                var v = piece.EnumerateArray().Select(e => e.GetInt32()).ToArray();
                if (check)
                {
                    Assert.True(v[0] < 0x2000, $"0x{v[0]:X4} is after the era");
                    Assert.DoesNotContain(v[0], playerItems);
                    Assert.DoesNotContain(v[0], blocking);
                }

                list.Add((v[1], v[2]));
            }

            return list;
        }

        var cove = Pieces("cove-flavor-statics.json", true);
        var britain = Pieces("greater-britain-flavor-statics.json", false);
        Assert.InRange(cove.Count, 300, 800);
        bool Close((int X, int Y) a, (int X, int Y) b) => (a.X - b.X) * (a.X - b.X) + (a.Y - b.Y) * (a.Y - b.Y) < 10 * 10;
        for (var i = 0; i < cove.Count; i++)
        {
            for (var j = i + 1; j < cove.Count; j++)
            {
                Assert.False(Close(cove[i], cove[j]), $"{cove[i]} and {cove[j]} are too close");
            }

            Assert.DoesNotContain(britain, b => Close(cove[i], b));
        }
    }
}
